Definition dealloc_p1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (M n b1 B T lo : Z) (ctx : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a4' a5' a6' a7' t3' t4' t5' t6' : word) (fr fd : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 INST) (Z_to_bv 64 M) (Z_to_bv 64 (M + 16)) (Z_to_bv 64 B)
                  a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (Z_to_bv 64 qchunk_entry') fc None m' (seg_rom asegs)
    /\ munch [(M, M + 24); (T + 2824, T + 2840); (bv_unsigned sp - 96, bv_unsigned sp)]%Z m m' /\ wmono asegs m m'
    /\ mem_inv asegs m'
    /\ rw_cells asegs m' M [C1 (Z_to_bv 8 3); C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx]
    /\ rw_cells asegs m' (M + 16) [C8 (Z_to_bv 64 18446744069414584320)]
    /\ rw_cells asegs m' (T + 2824) [C8 fr; C8 fd]
    /\ stk asegs m' lo (bv_unsigned sp).

Lemma dealloc_p1_spec : forall ra sp gp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (M n b1 B TCX T lo : Z) (ctx fr fd : word) (uw : list byte),
  (kHighShadowEnd < M)%Z -> (M mod 16 = 0)%Z -> (M + 24 <= lo)%Z -> (1 <= n < 2^32)%Z ->
  (0 <= b1 < 256)%Z -> (b1 mod 4 = 1)%Z ->
  rw_cells asegs m M [C1 (Z_to_bv 8 2); C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx] ->
  rw_cells asegs m (M + 16) [CB 8 uw] ->
  rw_cells asegs m (g_MFHooks + 8) [C8 (Z_to_bv 64 0)] ->
  thread_cells TCX T m -> (0 < TCX)%Z -> (TCX + 0xa0 <= lo)%Z -> (0 < T)%Z -> (T + 4096 <= 0x10000 \/ 0x662000 <= T)%Z ->
  (T + 4096 <= lo)%Z ->
  rw_cells asegs m (T + 2824) [C8 fr; C8 fd] ->
  (M + 24 <= T + 2824 \/ T + 2840 <= M)%Z -> (M + 24 <= TCX + 152 \/ TCX + 160 <= M)%Z ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 96)%Z -> (bv_unsigned sp <= 2^47)%Z ->
  mem_inv asegs m ->
  evt asegs (dealloc_p1_post ra sp gp (Z_to_bv 64 tpA) s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc M n b1 B T lo ctx m)
    (MS (mkR ra sp gp (Z_to_bv 64 tpA) t0 t1 t2 s0 s1 (Z_to_bv 64 INST) (Z_to_bv 64 (M + 16)) (Z_to_bv 64 0) (Z_to_bv 64 0)
             (Z_to_bv 64 B) (Z_to_bv 64 1) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 deallocate_entry) fc None m (seg_rom asegs)).
Proof.
